export function Walkthrough({
  title = "{{title}}",
  currentStep = {{currentStep}},
  totalSteps = {{totalSteps}},
  accent = "{{accent}}",
  orientation = "{{orientation}}",
}) {
  const steps = ["Create an account", "Import your data", "Invite your team", "Launch your first workflow"];
  const listStyle = {
    vertical: { display: "flex", flexDirection: "column" },
    horizontal: { display: "flex", flexDirection: "row", flexWrap: "wrap", gap: 16 },
    cards: { display: "flex", flexDirection: "row", flexWrap: "wrap", gap: 10 },
  }[orientation] ?? {};
  return (
    <div style={{ font: "16px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 20, maxWidth: 420, borderRadius: 14, border: "1px solid #24143018" }}>
      <h3 style={{ margin: "0 0 4px", fontSize: 16, fontWeight: 700 }}>{title}</h3>
      <p style={{ margin: "0 0 14px", fontSize: 12, color: "#24143090" }}>Step {currentStep} of {totalSteps}</p>
      <ol style={{ listStyle: "none", margin: 0, padding: 0, ...listStyle }}>
        {steps.map((label, i) => {
          const done = i < currentStep;
          const card = orientation === "cards";
          return (
            <li key={label} style={{
              display: "flex", alignItems: card ? "flex-start" : "center", flexDirection: card ? "column" : "row",
              gap: card ? 8 : 12, padding: card ? 12 : "8px 0", opacity: done ? 1 : 0.5,
              border: card ? "1.5px solid #24143018" : "none", borderRadius: card ? 10 : 0,
              flex: card ? "1 1 150px" : "initial",
            }}>
              <span style={{ width: 24, height: 24, borderRadius: 999, border: "1.5px solid " + (done ? accent : "#24143035"), background: done ? accent : "transparent", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 12, fontWeight: 700, flexShrink: 0 }}>{i + 1}</span>
              <span style={{ fontSize: 13.5, fontWeight: 600 }}>{label}</span>
            </li>
          );
        })}
      </ol>
    </div>
  );
}
